WITH RECURSIVE arbre AS (
  SELECT id, nom, parent_id, 0 AS profondeur FROM categories WHERE parent_id IS NULL
  UNION ALL
  SELECT c.id, c.nom, c.parent_id, a.profondeur + 1 FROM categories c INNER JOIN arbre a ON c.parent_id = a.id
)
SELECT id, nom, profondeur FROM arbre ORDER BY profondeur, nom;

WITH RECURSIVE descendants AS (
  SELECT id FROM categories WHERE id = 1
  UNION ALL
  SELECT c.id FROM categories c INNER JOIN descendants d ON c.parent_id = d.id
)
SELECT COUNT(*) AS nb_produits FROM produits WHERE categorie_id IN (SELECT id FROM descendants);

WITH RECURSIVE descendants AS (
  SELECT id FROM categories WHERE id = 2
  UNION ALL
  SELECT c.id FROM categories c INNER JOIN descendants d ON c.parent_id = d.id
)
SELECT COUNT(*) AS nb FROM categories WHERE id IN (SELECT id FROM descendants) AND id != 2;

WITH RECURSIVE arbre AS (
  SELECT id, nom, parent_id, nom AS chemin FROM categories WHERE parent_id IS NULL
  UNION ALL
  SELECT c.id, c.nom, c.parent_id, a.chemin || ' > ' || c.nom FROM categories c INNER JOIN arbre a ON c.parent_id = a.id
)
SELECT nom, chemin FROM arbre WHERE parent_id IS NOT NULL ORDER BY chemin;

